package com.xiaomiscalesync.crypto

import com.google.gson.JsonParser

/**
 * Test vector fixture, parsed from the committed `crypto_vectors.json`
 * generated by `scripts/gen_vectors.py`.
 */
sealed class VectorFixture {
    abstract val name: String

    /** AES-CCM fixture: output layout `ciphertext || 4-byte tag`. */
    data class Ccm(
        override val name: String,
        val key: ByteArray,
        val nonce: ByteArray,
        val aad: ByteArray?,
        val plaintext: ByteArray,
        val ciphertext: ByteArray,
    ) : VectorFixture()

    /** HKDF-SHA256 fixture: `output` is the first [length] bytes of OKM. */
    data class Hkdf(
        override val name: String,
        val ikm: ByteArray,
        val salt: ByteArray,
        val info: ByteArray,
        val length: Int,
        val output: ByteArray,
    ) : VectorFixture()
}

/** Loads committed test vectors from the unit-test resources. */
object Vectors {

    /**
     * Reads the test resource `<name>.json` and returns every fixture in it.
     * Example: `Vectors.load("crypto_vectors")`.
     */
    fun load(name: String): List<VectorFixture> {
        val url = checkNotNull(Vectors::class.java.classLoader?.getResource("$name.json")) {
            "missing test resource $name.json"
        }
        val array = url.openStream().bufferedReader().use { reader ->
            JsonParser.parseReader(reader).asJsonArray
        }
        return array.map { element ->
            val obj = element.asJsonObject
            when (val type = obj.get("type").asString) {
                "ccm" -> VectorFixture.Ccm(
                    name = obj.get("name").asString,
                    key = decodeHex(obj.get("key").asString),
                    nonce = decodeHex(obj.get("nonce").asString),
                    aad = if (obj.get("aad").isJsonNull) null
                          else decodeHex(obj.get("aad").asString),
                    plaintext = decodeHex(obj.get("plaintext").asString),
                    ciphertext = decodeHex(obj.get("ciphertext").asString),
                )
                "hkdf" -> VectorFixture.Hkdf(
                    name = obj.get("name").asString,
                    ikm = decodeHex(obj.get("ikm").asString),
                    salt = decodeHex(obj.get("salt").asString),
                    info = decodeHex(obj.get("info").asString),
                    length = obj.get("length").asInt,
                    output = decodeHex(obj.get("output").asString),
                )
                else -> error("unknown fixture type '$type' in $name.json")
            }
        }
    }

    /** Decodes a lowercase hex string into bytes. */
    fun decodeHex(hex: String): ByteArray {
        require(hex.length % 2 == 0) { "hex string must have even length: $hex" }
        val out = ByteArray(hex.length / 2)
        for (i in out.indices) {
            val hi = Character.digit(hex[2 * i], 16)
            val lo = Character.digit(hex[2 * i + 1], 16)
            require(hi >= 0 && lo >= 0) { "invalid hex string: $hex" }
            out[i] = ((hi shl 4) or lo).toByte()
        }
        return out
    }
}
